/// One window of a stream's piecewise rate schedule.
/// A segment reserves `allocation` tokens for the half-open window
/// `[start_time, end_time)` and accrues them pro rata over `basis_seconds`:
/// ```text
/// floor(allocation * elapsed_within_window / basis_seconds)
/// ```
/// `basis_seconds` is normally the window's own length, which makes the term
/// exact (no rounding at all) whenever `allocation` is a whole multiple of it —
/// the shape every renegotiated segment has, because it is priced as
/// `amount_per_second * window_length`. It is the *original* stream duration for
/// the first segment of a renegotiated stream, whose `allocation` is the deposit
/// the schedule started from: keeping that pair untouched is what makes an
/// accepted change unable to re-price the past.
/// Because each window is a sub-interval of the stream, the elapsed part of it
/// is never longer than `basis_seconds`, which is the condition
/// [`validate_capacity`] needs to guarantee the product cannot overflow.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RateSegment {
    /// First timestamp this segment accrues at (inclusive).
    pub start_time: u64,
    /// Last timestamp this segment accrues at (exclusive).
    pub end_time: u64,
    /// Tokens reserved for the window, as of the segment being accepted.
    pub allocation: i128,
    /// Divisor of the pro-rata term; see the struct docs.
    pub basis_seconds: u64,
}

impl RateSegment {
    /// Decodes the contract's map encoding of this struct.
    pub fn from_scval(value: &ScVal) -> Result<Self, crate::DecodeError> {
        let fields = crate::struct_fields(value, "RateSegment")?;
        Ok(Self {
            start_time: crate::scval_u64(crate::field(&fields, "start_time", "RateSegment")?, "RateSegment.start_time")?,
            end_time: crate::scval_u64(crate::field(&fields, "end_time", "RateSegment")?, "RateSegment.end_time")?,
            allocation: crate::scval_i128(crate::field(&fields, "allocation", "RateSegment")?, "RateSegment.allocation")?,
            basis_seconds: crate::scval_u64(crate::field(&fields, "basis_seconds", "RateSegment")?, "RateSegment.basis_seconds")?,
        })
    }
}

