/// (cancelled/depleted) streams keep their ids — read each stream's
/// `status` for lifecycle state.
pub fn recipient_streams_args(recipient: &str, offset: u32, limit: u32) -> Result<Vec<ScVal>, EncodeError> {
    Ok(vec![
        crate::address_to_scval(recipient)?,
        ScVal::U32(offset),
        ScVal::U32(limit),
    ])
}

